window.ART={};
const svgWrap=(body,label,view="0 0 600 300")=>'<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+view+'" role="img" aria-label="'+label+'">'+body+'</svg>';
const leaf=(x,y,r=0,s=1)=>'<g transform="translate('+x+' '+y+') rotate('+r+') scale('+s+')"><path d="M0 0 Q-35-40 0-65 Q35-40 0 0" fill="#8ba77e"/><path d="M0 0V-52" stroke="#607c55" stroke-width="1.4"/></g>';
const staffLines=(x1,x2,top=60,spacing=20)=>Array.from({length:5},(_,i)=>'<line x1="'+x1+'" y1="'+(top+i*spacing)+'" x2="'+x2+'" y2="'+(top+i*spacing)+'" stroke="#9eac99" stroke-width="1.4"/>').join("");
window.noteY=n=>({B4:100,A4:110,G4:120}[n]??100);
window.treble=(x=30,y=120)=>'<g transform="translate('+x+' '+y+') scale(.68)" fill="none" stroke="#47694f" stroke-width="4.5" stroke-linecap="round"><path d="M3 17C-21 7-14-23 4-22C24-21 24 5 9 8C-3 12-7 0-3-8M-9 12C-45-8 3-43 12-66C25-108-9-89 0-54L14 35C19 62-17 58-11 41"/><circle cx="-8" cy="44" r="4" fill="#47694f" stroke="none"/></g>';
window.drawStaff=function(notes,{labels=true,interactive=false,clef=true,active=-1}={}){const width=Math.max(360,130+notes.length*65),positions=notes.map((n,i)=>({n,x:100+i*(width-150)/Math.max(1,notes.length-1),y:noteY(n)}));let b=staffLines(28,width-20)+ (clef?treble(49,120):"");b+=positions.map(({n,x,y},i)=>'<g class="staff-note '+(i===active?"music-note-active":"")+'" '+(interactive?'tabindex="0" role="button" aria-label="听 '+n+'" data-note="'+n+'"':"")+'><rect class="hit-target" x="'+(x-24)+'" y="38" width="48" height="130" rx="12" fill="transparent"/><ellipse cx="'+x+'" cy="'+y+'" rx="9.5" ry="6.5" transform="rotate(-18 '+x+' '+y+')" fill="#3e6250"/><line x1="'+(x+(y<=100?-8:8))+'" y1="'+y+'" x2="'+(x+(y<=100?-8:8))+'" y2="'+(y+(y<=100?40:-40))+'" stroke="#3e6250" stroke-width="2.4"/>'+(labels?'<text x="'+x+'" y="185" text-anchor="middle" font-size="18" fill="#7d8f70">'+n[0]+'</text>':"")+'</g>').join("");return svgWrap(b,"高音谱表："+notes.join("、"),"0 0 "+width+" 210")};
window.drawFingering=function(note){const count={B4:1,A4:2,G4:3}[note]||1;let b='<text x="88" y="28" text-anchor="middle" font-size="16" fill="#5d7653">左手</text><text x="228" y="28" text-anchor="middle" font-size="16" fill="#5d7653">右手</text>';b+='<rect x="112" y="40" width="40" height="190" rx="17" fill="#dce4d4"/><rect x="252" y="40" width="40" height="190" rx="17" fill="#dce4d4"/>';const c=(x,y,pressed,label)=>'<circle cx="'+x+'" cy="'+y+'" r="14" fill="'+(pressed?"#466c50":"#fffdf7")+'" stroke="#72906a" stroke-width="2"/>'+(pressed?'<path d="m'+(x-6)+' '+y+' 4 4 8-9" fill="none" stroke="#fff8d9" stroke-width="2"/>':"")+'<text x="'+(x-25)+'" y="'+(y+4)+'" text-anchor="end" font-size="11" fill="#7f8f74">'+label+'</text>';b+=c(90,59,true,"拇指");["食指","中指","无名指"].forEach((label,i)=>{b+=c(132,97+i*47,i<count,label);b+=c(272,59+i*47,false,label)});b+=c(272,200,true,"小指");b+='<circle cx="57" cy="263" r="7" fill="#466c50"/><text x="72" y="268" font-size="12" fill="#718169">按下</text><circle cx="159" cy="263" r="7" fill="#fffdf7" stroke="#72906a"/><text x="174" y="268" font-size="12" fill="#718169">不按</text>';return svgWrap(b,note+" 基本指法，左手拇指和"+count+"个手指按下，通常右小指按降E键","0 0 330 288")};
ART.flute=()=>svgWrap('<defs><linearGradient id="metal" x2="0" y2="1"><stop stop-color="#fffdf1"/><stop offset=".4" stop-color="#a9b4a1"/><stop offset=".65" stop-color="#fdfcf0"/><stop offset="1" stop-color="#889980"/></linearGradient></defs><g transform="translate(35 20) rotate(-14 260 140)"><path d="M145 95H82C38 95 38 160 82 160H480" fill="none" stroke="#879980" stroke-width="24" stroke-linecap="round"/><path d="M145 95H82C38 95 38 160 82 160H480" fill="none" stroke="url(#metal)" stroke-width="19" stroke-linecap="round"/><ellipse cx="132" cy="95" rx="23" ry="15" fill="#d5dccd" stroke="#8ea184"/><ellipse cx="132" cy="95" rx="10" ry="6" fill="#5d7356"/><path d="M165 142H430" stroke="#84987a" stroke-width="3"/>'+[195,234,273,325,364,403].map((x,i)=>'<path d="M'+x+' 143v11" stroke="#84987a" stroke-width="4"/><ellipse cx="'+x+'" cy="157" rx="14" ry="10" fill="#eaf0df" stroke="#8b9f80" stroke-width="2"/><ellipse cx="'+x+'" cy="157" rx="8" ry="5" fill="#c8d4bc"/>').join("")+'<path d="M452 146v29" stroke="#728d68" stroke-width="3"/><ellipse cx="458" cy="149" rx="14" ry="8" fill="#d2dec5" stroke="#839a78"/><path d="M171 148v25M305 148v25M445 148v25" stroke="#c1cdb5" stroke-width="2"/></g>','儿童弯头长笛示意');
